import { test, expect } from '@playwright/test';

test.describe('Error Message Screen Reader Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should display error messages with accessible labels and roles', async ({ page }) => {
    // Intercept the API call to simulate an error
    await page.route('**/api/submit', route => {
      route.abort('failed');
    });

    // Fill in form fields
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('test@example.com');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('Password123');

    // Click submit button
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Wait for error message to appear
    await page.waitForTimeout(500);

    // Verify error message is visible
    const errorMessage = page.getByText('Email is required');
    await expect(errorMessage).toBeVisible();

    // Verify error message has an accessible role
    const errorContainer = page.locator('[data-testid="error-container"]');
    await expect(errorContainer).toBeVisible();
    await expect(errorContainer).toHaveAttribute('role', 'alert');

    // Verify error message has an accessible label
    await expect(errorMessage).toHaveAttribute('aria-live', 'polite');
  });

  test('should handle multiple error messages with proper ARIA attributes', async ({ page }) => {
    // Intercept the API call to simulate multiple errors
    await page.route('**/api/submit', route => {
      route.abort('failed');
    });

    // Fill in form fields with invalid data
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('invalid-email');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('short');

    // Click submit button
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Wait for error messages to appear
    await page.waitForTimeout(500);

    // Verify both error messages are visible
    const emailError = page.getByText('Invalid email format');
    await expect(emailError).toBeVisible();

    const passwordError = page.getByText('Password must be at least 8 characters');
    await expect(passwordError).toBeVisible();

    // Verify error container has correct role and multiple messages
    const errorContainer = page.locator('[data-testid="error-container"]');
    await expect(errorContainer).toHaveAttribute('role', 'alert');

    // Verify all error messages are within the alert container
    const allErrorMessages = page.locator('[data-testid="error-message"]');
    const count = await allErrorMessages.count();
    expect(count).toBe(2);
  });
});
